const {chromium}=require(process.env.MX_PLAYWRIGHT_MODULE||'playwright-core');const fs=require('node:fs');
(async()=>{const b=await chromium.launch({executablePath:process.env.MX_CHROME||'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless:true});let p=await b.newPage({viewport:{width:1200,height:1200}});let errors=[],results=[];p.on('pageerror',e=>errors.push(String(e)));const out='docs/styles/style2/implementation/round1/edge';fs.mkdirSync(out,{recursive:true});
const cases=[{name:'main-voice',scene:'media-voice',seats:8,action:1,bb:1},{name:'main-video',scene:'media-video',seats:8,action:1,bb:1},{name:'voice-safe34',scene:'media-voice',action:1,safeBottom:34},{name:'video-safe34',scene:'media-video',action:1,safeBottom:34},{name:'short-safe34',scene:'media-video',action:1,width:320,height:400,safeBottom:34},{name:'short-six',scene:'six',width:320,height:400},{name:'wide-raise',scene:'raise',width:844,height:440,orientation:'auto'},{name:'long-en',scene:'long',locale:'en',long:1},{name:'short-dual',scene:'board-dual-turn',width:375,height:500},{name:'video-long',scene:'media-video',height:956,action:1}];
for(const c of cases){await p.goto((process.env.MX_AUDIT_URL||'http://127.0.0.1:5183')+'/tests/fixtures/layout-audit.html?'+new URLSearchParams({skin:'style2',layout:'balanced',width:440,height:782,...c}));await p.locator('#audit-stage[data-ready=true]').waitFor({timeout:60000});await p.locator('#audit-stage').screenshot({path:out+'/'+c.name+'.png'});let metrics=await p.evaluate(()=>{const r=document.querySelector('#audit-stage').getBoundingClientRect(),nav=document.querySelector('.mx-navigation').getBoundingClientRect();return [...document.querySelectorAll('.mx-nav-button,.mx-operation-row button,.mx-quick-bet,.mx-raise-confirm,.mx-operation-cancel')].filter(e=>e.checkVisibility()).map(e=>{const x=e.getBoundingClientRect();return {class:e.className,inside:x.left>=r.left-.5&&x.right<=r.right+.5&&x.top>=r.top-.5&&x.bottom<=r.bottom+.5,w:x.width,h:x.height,aboveNav:e.classList.contains('mx-nav-button')||x.bottom<=nav.top+.5}})});if(c.name==='short-safe34'){
const before=await p.locator('.mx-navigation').boundingBox();const scroll=await p.locator('.mx-viewport').evaluate(e=>{e.scrollTop=e.scrollHeight;return {top:e.scrollTop,max:e.scrollHeight-e.clientHeight}});
await p.locator('#audit-stage').screenshot({path:out+'/short-safe34-scrolled.png'});
const after=await p.locator('.mx-navigation').boundingBox();if(scroll.top<=0||Math.abs(before.y-after.y)>1)errors.push('Short-screen scroll or fixed navigation failed');
}
if(c.name==='wide-raise'){
await p.locator('.mx-raise-range').press('ArrowRight');await p.locator('.mx-raise-confirm').click();
if(!(await p.locator('#audit-log').innerText()).includes('本地操作成功：加注'))errors.push('Landscape raise submit failed');
}
results.push({case:c,metrics,errors:errors.splice(0)});}
fs.writeFileSync(out+'/results.json',JSON.stringify(results,null,2));console.log(results.map(r=>({case:r.case.name,errors:r.errors,violations:r.metrics.filter(m=>!m.inside||(!m.aboveNav&&r.case.orientation!=='auto'))})));if(results.some(r=>r.errors.length||r.metrics.some(m=>!m.inside||(!m.aboveNav&&r.case.orientation!=='auto'))))process.exitCode=1;await b.close()})();
